package com.hospital.smartqueue.doctor.application; import com.hospital.smartqueue.common.domain.*; import com.hospital.smartqueue.common.infrastructure.AuditService; import com.hospital.smartqueue.doctor.domain.Doctor; import com.hospital.smartqueue.doctor.infrastructure.DoctorRepository; import com.hospital.smartqueue.hospital.infrastructure.HospitalRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class DoctorService{private final DoctorRepository doctors;private final HospitalRepository hospitals;private final AuditService audit;public DoctorService(DoctorRepository d,HospitalRepository h,AuditService a){doctors=d;hospitals=h;audit=a;}@Transactional public Doctor register(UUID h,String c,String n,String s,String r,Doctor.Status st){if(!hospitals.existsById(h))throw new NotFoundException("Hospital not found");if(c==null||c.isBlank()||n==null||n.isBlank()||s==null||s.isBlank()||r==null||r.isBlank())throw new DomainException("Doctor details are required");Doctor d=doctors.save(new Doctor(UUID.randomUUID(),h,c.trim(),n.trim(),s.trim(),r.trim(),st==null?Doctor.Status.ACTIVE:st));audit.record("DOCTOR_REGISTERED","DOCTOR",d.getId(),h,null);return d;}public List<Doctor> list(UUID h){if(!hospitals.existsById(h))throw new NotFoundException("Hospital not found");return doctors.findByHospitalId(h);}@Transactional public Doctor status(UUID h,UUID id,Doctor.Status s){Doctor d=doctors.findById(id).filter(x->x.getHospitalId().equals(h)).orElseThrow(()->new NotFoundException("Doctor not found"));d.setStatus(s);audit.record("DOCTOR_STATUS_CHANGED","DOCTOR",id,h,null);return d;}}
